<?php
$counts=rows("SELECT COUNT(*) total, SUM(status IN ('Pending','Submitted','Under Review')) pending, SUM(status='Ready for Pickup') ready, SUM(status='Released') released FROM document_requests")[0];
$pending=rows("SELECT COUNT(*) total FROM users WHERE role='resident' AND status='Pending'")[0]['total'];
?>
<section class="welcome-card"><p class="eyebrow">COMMUNITY SERVICES</p><h2>Welcome, <?= e($admin['first_name']) ?>.</h2><p>Review registrations, prepare documents, and keep residents informed.</p></section>
<div class="metrics"><?php foreach (['Pending users'=>$pending,'Total requests'=>$counts['total'],'Awaiting review'=>$counts['pending']??0,'Ready for pickup'=>$counts['ready']??0,'Released'=>$counts['released']??0] as $label=>$count): ?><article class="metric"><span><?= e($label) ?></span><strong><?= (int)$count ?></strong></article><?php endforeach; ?></div>
<section class="panel dashboard-actions"><h2>Quick actions</h2><div class="button-row"><a class="button primary" href="index.php?page=requests">All Requests</a><?php foreach (['notifications'=>'Notification','documents'=>'Documents','residents'=>'Residents','requests'=>'Document Request','reports'=>'Reports','settings'=>'Settings'] as $key=>$label): ?><a class="button secondary" href="index.php?page=<?= e($key) ?>"><?= e($label) ?></a><?php endforeach; ?></div></section>
<section class="panel dashboard-actions"><h2>Recent admin activity</h2><div class="table-scroll"><table><thead><tr><th>Admin</th><th>Action</th><th>Record</th><th>When</th></tr></thead><tbody><?php foreach(rows('SELECT l.*,u.first_name,u.last_name FROM admin_audit_logs l JOIN users u ON u.id=l.admin_id ORDER BY l.id DESC LIMIT 10') as $log): ?><tr><td><?= e($log['first_name'].' '.$log['last_name']) ?></td><td><?= e(str_replace('_',' ',$log['action'])) ?></td><td><?= e($log['entity_type'].' #'.$log['entity_id']) ?></td><td><?= e($log['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
